          </Link>
        ) : null}
        {maySettings ? (
          <Link href={`${base}/settings`} className="ml-auto text-slate-600">
            Settings
          </Link>
        ) : null}
      </nav>

      <div>{props.children}</div>
    </div>
  );
}
